// Policy evaluation stub for cross-tenant access
function evaluateToken(token, context) {
  if (!token || token.expiresAt < Date.now()) {
    return { allowed: false, reason: 'Token expired or invalid' };
  }
  if (token.tenantId !== context.targetTenantId) {
    return { allowed: false, reason: 'Cross-tenant violation' };
  }
  return { allowed: true, scope: token.scope };
}
```

